local phase = "guarding"
local started = false
function event_spawn(e)
  if started then return end
  started = true
  -- Spawn delivery starts the guards' hostility separately from Peffin's walk.
  -- Keep the shared movement/hate transaction boundary intact.
  e.self:AddToHateList(e.other, 1)
end
function event_signal(e)
  if e.signal == 9 and phase == "guarding" then
    phase = "leaving"; eq.set_timer("leave", 630000)
  end
end
function event_timer(e)
  if e.timer == "leave" and phase == "leaving" then
    phase = "ended"; eq.stop_timer("leave"); eq.depop()
  end
end
function event_death_complete(e) phase = "ended"; eq.stop_timer("leave") end
